<script setup lang="ts">
import {onBeforeUnmount,watch} from 'vue'
import {state,attempt,soundPreview} from '../store'
import {kitState,savedKits,soundRoots,saveSoundKit,applySoundKit,matchSounds,cancelSoundSearch} from '../kits'
import {midiNoteName} from '../lib/format'
import AssetBrowser from './AssetBrowser.vue'
import KitPreview from './KitPreview.vue'
onBeforeUnmount(cancelSoundSearch)
watch(()=>[kitState.query,kitState.scope,kitState.scope==='selected'?state.selected:undefined],cancelSoundSearch)
function search(){return matchSounds(kitState.query,kitState.scope==='selected'?state.selected:undefined)}
</script>
<template><section class="kit-workspace workspace-ui" aria-label="Sound kits"><aside class="kit-console"><h2>KIT</h2><label>NAME<input v-model="kitState.name" aria-label="Kit name" placeholder="Name this sound kit"/></label><div class="kit-actions"><button :disabled="kitState.saving||kitState.busy||!!soundPreview.kit||!kitState.name.trim()" @click="attempt(()=>saveSoundKit())">SAVE KIT</button><button :disabled="kitState.saving||kitState.busy||!!soundPreview.kit||!kitState.name.trim()" @click="attempt(()=>saveSoundKit(true))">SAVE A COPY</button></div><h3>SAVED KITS</h3><button v-for="field in savedKits" :key="field.key" class="saved-kit" :class="{active:kitState.name===field.value.name}" :disabled="kitState.busy" @click="attempt(()=>applySoundKit(field.value))"><b>{{field.value.name}}</b><small>{{field.value.keys.length}} sounds</small></button><p v-if="!savedKits.length">Save the current sounds to create your first kit.</p></aside><div class="kit-matching"><form class="kit-search" @submit.prevent="attempt(search)"><input v-model="kitState.query" aria-label="Semantic kit search" placeholder="Describe a kit: dusty jazz, heavy rock, analog 909…"/><select v-model="kitState.scope" aria-label="Sound matching target"><option value="all">All keywaves</option><option value="selected">{{midiNoteName(state.selected)}} only</option></select><button :disabled="kitState.busy||!kitState.query.trim()">{{kitState.busy?'MATCHING…':'AUTO BIND'}}</button></form><div class="kit-status"><span>{{kitState.status||'Auto Bind previews matching sounds. Apply Kit keeps them.'}}</span><span>{{soundRoots.length}} sound {{soundRoots.length===1?'folder':'folders'}}</span></div><KitPreview/><AssetBrowser sound-only :assign-to="state.selected"/></div></section></template>
<style scoped>
.kit-workspace{display:grid;grid-template-columns:230px minmax(0,1fr);height:100%;min-height:0;gap:9px}.kit-console{background:var(--panel-lo);border:1px solid var(--line);padding:12px;display:flex;flex-direction:column;gap:9px;overflow:auto}.kit-console h2{font:12px monospace;letter-spacing:.1em;margin:0 0 6px}.kit-console h3{font:10px monospace;letter-spacing:.1em;color:var(--text-dim);margin:13px 0 3px}.kit-console label{display:flex;align-items:stretch;flex-direction:column;gap:5px;font:9px monospace}.kit-console input{width:100%;min-width:0}.kit-actions{display:grid;gap:5px}.kit-actions button{font:10px monospace;padding:7px}.saved-kit{display:flex;align-items:center;justify-content:space-between;text-align:left;gap:8px}.saved-kit b{font-size:11px;font-weight:500}.saved-kit small{font:9px monospace;white-space:nowrap}.kit-console p{font:11px/1.5 sans-serif;color:var(--text-dim)}.kit-matching{display:flex;flex-direction:column;min-width:0;min-height:0;border:1px solid var(--line);background:var(--panel-lo);padding:10px;gap:9px}.kit-search{display:flex;gap:7px}.kit-search input{flex:1;min-width:0}.kit-search button,.kit-search select{font:11px monospace}.kit-status{display:flex;justify-content:space-between;gap:10px;color:var(--text-dim);font:10px/1.4 monospace}.kit-status>span:last-child{white-space:nowrap}.kit-matching :deep(.asset-browser){min-height:0;flex:1;height:auto}.kit-matching :deep(.browser-body){min-height:0}@media(max-width:1050px){.kit-workspace{grid-template-columns:190px minmax(0,1fr)}.kit-search{flex-wrap:wrap}.kit-search input{flex-basis:60%}}
